1	import React, { useState } from "react";
2	import { Button } from "@/components/ui/button";
3	import { Badge } from "@/components/ui/badge";
4	import { Checkbox } from "@/components/ui/checkbox";
5	import { TableCell, TableRow } from "@/components/ui/table";
6	import { Tooltip, TooltipContent, TooltipTrigger, TooltipProvider } from "@/components/ui/tooltip";
7	import { Phone, Mail, MapPin, FileText, Archive, Linkedin } from "lucide-react";
8	import { extractLinkedInUrl } from "@/lib/linkedin";
9	import { toast } from "sonner";
10	import type { Result } from "@/pages/Index";
11	import EmailOutreachDialog from "@/components/candidate/EmailOutreachDialog";
12	import type { HiringStage } from "@/hooks/useStageTracker";
13	
14	interface CandidateRowProps {
15	  result: Result;
16	  index: number;
17	  isSelected: boolean;
18	  isActive: boolean;
19	  jobId?: string | null;
20	  jobTitle?: string | null;
21	  onSelect: (id: string) => void;
22	  onToggleSelect: (resumeId: string) => void;
23	  onDownload: (filePath: string, filename: string) => void;
24	  onDismiss: (resumeId: string) => void;
25	  formatCandidateName: (filename: string) => string;
26	  currentStage?: HiringStage | null;
27	  isDuplicate?: boolean;
28	}
29	
30	const getScoreColor = (score: number) => {
31	  if (score >= 70) return "bg-score-skills";
32	  if (score >= 40) return "bg-warning";
33	  return "bg-destructive";
34	};
35	
36	const getScoreTextColor = (score: number) => {
37	  if (score >= 70) return "text-score-skills";
38	  if (score >= 40) return "text-warning";
39	  return "text-destructive";
40	};
41	
42	const STAGE_BADGE_CLASSES: Record<string, string> = {
43	  applied: "border-border bg-muted/50 text-muted-foreground",
44	  screened: "border-blue-200 bg-blue-50 text-blue-700 dark:border-blue-700 dark:bg-blue-900/20 dark:text-blue-400",
45	  interview: "border-purple-200 bg-purple-50 text-purple-700 dark:border-purple-700 dark:bg-purple-900/20 dark:text-purple-400",
46	  offer: "border-amber-200 bg-amber-50 text-amber-700 dark:border-amber-700 dark:bg-amber-900/20 dark:text-amber-400",
47	  hired: "border-emerald-200 bg-emerald-50 text-emerald-700 dark:border-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400",
48	  rejected: "border-red-200 bg-red-50 text-red-700 dark:border-red-700 dark:bg-red-900/20 dark:text-red-400",
49	};
50	
51	const getStrengthLabel = (score: number): { label: string; variant: "success" | "warning" | "destructive" } => {
52	  if (score >= 70) return { label: "Strong", variant: "success" };
53	  if (score >= 40) return { label: "Good", variant: "warning" };
54	  return { label: "Weak", variant: "destructive" };
55	};
56	
57	const CandidateRow = ({
58	  result: r,
59	  index,
60	  isSelected,
61	  isActive,
62	  jobId,
63	  jobTitle,
64	  onSelect,
65	  onToggleSelect,
66	  onDownload,
67	  onDismiss,
68	  formatCandidateName,
69	  currentStage,
70	  isDuplicate,
71	}: CandidateRowProps) => {
72	  const [emailDialogOpen, setEmailDialogOpen] = useState(false);
73	  const strength = !r.pending ? getStrengthLabel(r.overall_score) : null;
74	  const linkedinUrl = extractLinkedInUrl(r);
75	
76	  return (
77	    <>
78	      <TableRow
79	        className={`transition-colors animate-in fade-in slide-in-from-bottom-1 duration-200 ${r.pending ? "opacity-50 cursor-default" : "cursor-pointer"} ${isActive ? "bg-primary/5 hover:bg-primary/5" : "hover:bg-muted/50"}`}
80	        style={{ animationDelay: `${Math.min(index * 40, 400)}ms`, animationFillMode: "backwards" }}
81	        onClick={() => !r.pending && onSelect(r.id)}
82	      >
83	        <TableCell onClick={(e) => e.stopPropagation()}>
84	          <Checkbox checked={isSelected} onCheckedChange={() => onToggleSelect(r.resume_id)} />
85	        </TableCell>
86	        <TableCell className="text-center">
87	          {r.pending
88	            ? <span className="text-sm text-muted-foreground">—</span>
89	            : <span className="text-sm font-medium tabular-nums text-muted-foreground">{index + 1}</span>}
90	        </TableCell>
91	        <TableCell className="font-medium">
92	          <div className="flex flex-col gap-0.5">
93	            <div className="flex items-center gap-1.5 flex-wrap">
94	              <span className="text-sm">{r.candidate_name || formatCandidateName(r.filename)}</span>
95	              {isDuplicate && (
96	                <Badge variant="outline" className="text-[11px] px-1.5 py-0 border-orange-300 text-orange-600 bg-orange-50">
97	                  Duplicate
98	                </Badge>
99	              )}
100	              {!r.pending && currentStage && currentStage !== "applied" && (
101	                <Badge
102	                  variant="outline"
103	                  className={`text-[11px] px-1.5 py-0 h-4 capitalize border font-medium ${STAGE_BADGE_CLASSES[currentStage] ?? ""}`}
104	                >
105	                  {currentStage}
106	                </Badge>
107	              )}
108	            </div>
109	            {r.candidate_location && (
110	              <span className="flex items-center gap-1 text-xs text-muted-foreground">
111	                <MapPin className="h-3 w-3" /> {r.candidate_location}
112	              </span>
113	            )}
114	          </div>
115	        </TableCell>
116	        <TableCell>
117	          {r.pending ? (
118	            <Badge variant="outline" className="text-[11px]">Pending</Badge>
119	          ) : (
