import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const ALLOWED_ORIGINS = [
  Deno.env.get("APP_URL") || "https://rankora.co",
  "https://www.rankora.co",
  "http://localhost:8080",
  "http://localhost:5173",
];

function getCorsOrigin(req: Request): string {
  const origin = req.headers.get("origin") || "";
  return ALLOWED_ORIGINS.includes(origin) ? origin : ALLOWED_ORIGINS[0];
}

const OPENAI_API_KEY = Deno.env.get("OPENAI_API_KEY")!;
const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

serve(async (req) => {
  const corsHeaders = {
    "Access-Control-Allow-Origin": getCorsOrigin(req),
    "Access-Control-Allow-Headers":
      "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
  };
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  try {
    // Auth check
    const authHeader = req.headers.get("Authorization");
    if (!authHeader) throw new Error("No auth header");

    const token = authHeader.replace("Bearer ", "");
    const anonKey = Deno.env.get("SUPABASE_PUBLISHABLE_KEY") || Deno.env.get("SUPABASE_ANON_KEY")!;
    const supabaseUser = createClient(SUPABASE_URL, anonKey, {
      global: { headers: { Authorization: authHeader } },
    });
    const { data: claimsData, error: claimsError } = await supabaseUser.auth.getClaims(token);
    if (claimsError || !claimsData?.claims) throw new Error("Unauthorized");

    // No credit deduction — generation is free

    const body = await req.json();
    const {
      job_title,
      company_name,
      key_responsibilities,
      requirements,
      nice_to_haves,
      employment_type,
      location,
      salary_range,
      tone,
    } = body;

    if (!job_title?.trim()) throw new Error("Missing job_title");
    if (!key_responsibilities?.trim()) throw new Error("Missing key_responsibilities");
    if (!requirements?.trim()) throw new Error("Missing requirements");

    const toneInstruction =
      tone === "Casual"
        ? "Use a friendly, approachable tone. Avoid stiff corporate language."
        : tone === "Startup"
        ? "Use an energetic, mission-driven startup tone. Emphasize impact and growth."
        : "Use a professional, formal tone suitable for established companies.";

    const systemPrompt = `You are an expert HR copywriter and technical recruiter specializing in ATS-optimized job descriptions. Your task is to generate a complete, compelling job description from the provided inputs.

GENERATION GUIDELINES:
- Structure the JD with clear sections: About the Role, Key Responsibilities, Requirements, Nice-to-Have, What We Offer
- Use inclusive, bias-free language
- Ensure ATS-friendliness: standard section headers, bullet points, spell out acronyms on first use
- ${toneInstruction}
- Keep the About the Role section to 2-4 sentences that capture the essence and impact of the position
- Key Responsibilities: 5-8 clear bullet points using action verbs
- Requirements: 5-8 must-have qualifications, specific and measurable
- Nice-to-Have: 3-5 bonus qualifications
- What We Offer: 4-6 benefits/perks bullets (use generic competitive offerings if none provided)
- If company_name, location, employment_type, or salary_range are provided, incorporate them naturally

Return ONLY valid JSON with this exact structure:
{
  "job_description": "the complete formatted job description as a single string with \\n for line breaks",
  "sections": {
    "about": "...",
    "responsibilities": "...",
    "requirements": "...",
    "nice_to_haves": "...",
    "benefits": "..."
  }
}`;

    const userMessage = [
      `Job Title: ${job_title.trim()}`,
      company_name ? `Company: ${company_name.trim()}` : null,
      employment_type ? `Employment Type: ${employment_type}` : null,
      location ? `Location: ${location.trim()}` : null,
      salary_range ? `Salary Range: ${salary_range.trim()}` : null,
      `\nKey Responsibilities:\n${key_responsibilities.trim()}`,
      `\nRequirements:\n${requirements.trim()}`,
      nice_to_haves ? `\nNice-to-Have:\n${nice_to_haves.trim()}` : null,
    ]
      .filter(Boolean)
      .join("\n");

    const response = await fetch("https://api.openai.com/v1/chat/completions", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${OPENAI_API_KEY}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model: "gpt-4o",
        messages: [
          { role: "system", content: systemPrompt },
          { role: "user", content: userMessage },
        ],
        response_format: { type: "json_object" },
        temperature: 0.4,
      }),
    });

    if (!response.ok) {
      const errBody = await response.text();
      throw new Error(`OpenAI API error ${response.status}: ${errBody.slice(0, 200)}`);
    }

    const aiData = await response.json();
    const content = aiData.choices?.[0]?.message?.content;
    if (!content) throw new Error("OpenAI returned empty response");

    const parsed = JSON.parse(content);

    if (!parsed.job_description || !parsed.sections) {
      throw new Error("Unexpected response structure from OpenAI");
    }

    console.log(`generate-jd complete for job_title: ${job_title}`);

    return new Response(
      JSON.stringify({
        success: true,
        job_description: parsed.job_description,
        sections: parsed.sections,
      }),
      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  } catch (err) {
    console.error("generate-jd error:", err);
    return new Response(
      JSON.stringify({ error: err instanceof Error ? err.message : String(err) }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});

import { useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Loader2, Sparkles, CheckCircle2, RefreshCw } from "lucide-react";

interface JDGeneratorDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onGenerated: (jd: string) => void;
}

interface GeneratePayload {
  job_title: string;
  company_name: string;
  key_responsibilities: string;
  requirements: string;
  nice_to_haves: string;
  employment_type: string;
  location: string;
  salary_range: string;
  tone: string;
}

const EMPTY_FORM: GeneratePayload = {
  job_title: "",
  company_name: "",
  key_responsibilities: "",
  requirements: "",
  nice_to_haves: "",
  employment_type: "Full-time",
  location: "",
  salary_range: "",
  tone: "Professional",
};

const JDGeneratorDialog = ({ open, onOpenChange, onGenerated }: JDGeneratorDialogProps) => {
  const [form, setForm] = useState<GeneratePayload>(EMPTY_FORM);
  const [loading, setLoading] = useState(false);
  const [generatedJd, setGeneratedJd] = useState<string | null>(null);
  const [fieldErrors, setFieldErrors] = useState<Partial<Record<keyof GeneratePayload, string>>>({});

  const update = (key: keyof GeneratePayload, value: string) => {
    setForm((prev) => ({ ...prev, [key]: value }));
    if (fieldErrors[key]) setFieldErrors((prev) => ({ ...prev, [key]: undefined }));
  };

  const validate = (): boolean => {
    const errors: Partial<Record<keyof GeneratePayload, string>> = {};
    if (!form.job_title.trim()) errors.job_title = "Job title is required";
    if (!form.key_responsibilities.trim()) errors.key_responsibilities = "Key responsibilities are required";
    if (!form.requirements.trim()) errors.requirements = "Requirements are required";
    setFieldErrors(errors);
    return Object.keys(errors).length === 0;
  };

  const handleGenerate = async () => {
    if (!validate()) return;
    setLoading(true);
    try {
      const { data, error } = await supabase.functions.invoke("generate-jd", {
        body: {
          job_title: form.job_title.trim(),
          company_name: form.company_name.trim() || undefined,
          key_responsibilities: form.key_responsibilities.trim(),
          requirements: form.requirements.trim(),
          nice_to_haves: form.nice_to_haves.trim() || undefined,
          employment_type: form.employment_type || undefined,
          location: form.location.trim() || undefined,
          salary_range: form.salary_range.trim() || undefined,
          tone: form.tone || "Professional",
        },
      });
      if (error) throw error;
      if (data?.error) throw new Error(data.error);
      setGeneratedJd(data.job_description as string);
      toast.success("Job description generated");
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : "Failed to generate JD");
    } finally {
      setLoading(false);
    }
  };

  const handleUse = () => {
    if (!generatedJd) return;
    onGenerated(generatedJd);
    onOpenChange(false);
    toast.success("Job description applied");
  };

  const handleOpenChange = (nextOpen: boolean) => {
    if (loading) return;
    if (!nextOpen) {
      setForm(EMPTY_FORM);
      setGeneratedJd(null);
      setFieldErrors({});
    }
    onOpenChange(nextOpen);
  };

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogContent className="max-w-5xl w-full max-h-[90vh] overflow-hidden flex flex-col">
        <DialogHeader className="shrink-0">
          <DialogTitle className="flex items-center gap-2">
            <Sparkles className="h-5 w-5 text-primary" />
            Generate Job Description
          </DialogTitle>
        </DialogHeader>

        <div className="flex-1 overflow-y-auto min-h-0">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pb-4">
            {/* LEFT — form inputs */}
            <div className="space-y-4">
              <div className="space-y-1.5">
                <Label htmlFor="jdg-title" className="text-xs font-medium">
                  Job Title <span className="text-destructive">*</span>
                </Label>
                <Input
                  id="jdg-title"
                  placeholder="e.g. Senior React Developer"
                  value={form.job_title}
                  onChange={(e) => update("job_title", e.target.value)}
                  className={fieldErrors.job_title ? "border-destructive" : ""}
                />
                {fieldErrors.job_title && (
                  <p className="text-xs text-destructive">{fieldErrors.job_title}</p>
                )}
              </div>

              <div className="space-y-1.5">
                <Label htmlFor="jdg-company" className="text-xs font-medium">Company Name</Label>
                <Input
                  id="jdg-company"
                  placeholder="e.g. Acme Corp"
                  value={form.company_name}
                  onChange={(e) => update("company_name", e.target.value)}
                />
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1.5">
                  <Label className="text-xs font-medium">Employment Type</Label>
                  <Select value={form.employment_type} onValueChange={(v) => update("employment_type", v)}>
                    <SelectTrigger className="h-9 text-sm">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="Full-time">Full-time</SelectItem>
                      <SelectItem value="Part-time">Part-time</SelectItem>
                      <SelectItem value="Contract">Contract</SelectItem>
                      <SelectItem value="Freelance">Freelance</SelectItem>
                      <SelectItem value="Internship">Internship</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-1.5">
                  <Label className="text-xs font-medium">Tone</Label>
                  <Select value={form.tone} onValueChange={(v) => update("tone", v)}>
                    <SelectTrigger className="h-9 text-sm">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="Professional">Professional</SelectItem>
                      <SelectItem value="Casual">Casual</SelectItem>
                      <SelectItem value="Startup">Startup</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1.5">
                  <Label htmlFor="jdg-location" className="text-xs font-medium">Location</Label>
                  <Input
                    id="jdg-location"
                    placeholder="e.g. Remote / NYC"
                    value={form.location}
                    onChange={(e) => update("location", e.target.value)}
                  />
                </div>
                <div className="space-y-1.5">
                  <Label htmlFor="jdg-salary" className="text-xs font-medium">Salary Range</Label>
                  <Input
                    id="jdg-salary"
                    placeholder="e.g. $80k – $120k"
                    value={form.salary_range}
                    onChange={(e) => update("salary_range", e.target.value)}
                  />
                </div>
              </div>

              <div className="space-y-1.5">
                <Label htmlFor="jdg-responsibilities" className="text-xs font-medium">
                  Key Responsibilities <span className="text-destructive">*</span>
                </Label>
                <Textarea
                  id="jdg-responsibilities"
                  placeholder={"- Build and maintain React components\n- Collaborate with design team\n- Write unit tests"}
                  value={form.key_responsibilities}
                  onChange={(e) => update("key_responsibilities", e.target.value)}
                  className={`min-h-[100px] resize-none text-sm ${fieldErrors.key_responsibilities ? "border-destructive" : ""}`}
                />
                {fieldErrors.key_responsibilities && (
                  <p className="text-xs text-destructive">{fieldErrors.key_responsibilities}</p>
                )}
              </div>

              <div className="space-y-1.5">
                <Label htmlFor="jdg-requirements" className="text-xs font-medium">
                  Requirements <span className="text-destructive">*</span>
                </Label>
                <Textarea
                  id="jdg-requirements"
                  placeholder={"- 3+ years React experience\n- TypeScript proficiency\n- BS in Computer Science or equivalent"}
                  value={form.requirements}
                  onChange={(e) => update("requirements", e.target.value)}
                  className={`min-h-[100px] resize-none text-sm ${fieldErrors.requirements ? "border-destructive" : ""}`}
                />
                {fieldErrors.requirements && (
                  <p className="text-xs text-destructive">{fieldErrors.requirements}</p>
                )}
              </div>

              <div className="space-y-1.5">
                <Label htmlFor="jdg-nice" className="text-xs font-medium">Nice-to-Have</Label>
                <Textarea
                  id="jdg-nice"
                  placeholder={"- Experience with Next.js\n- Open source contributions"}
                  value={form.nice_to_haves}
                  onChange={(e) => update("nice_to_haves", e.target.value)}
                  className="min-h-[80px] resize-none text-sm"
                />
              </div>
            </div>

            {/* RIGHT — preview */}
            <div className="flex flex-col gap-2">
              <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">
                Generated Job Description
                {generatedJd && (
                  <span className="ml-2 text-[11px] normal-case font-normal text-muted-foreground">(editable)</span>
                )}
              </p>
              {!generatedJd && !loading && (
                <div className="flex-1 flex flex-col items-center justify-center rounded-lg border-2 border-dashed border-border bg-muted/20 min-h-[400px] gap-3 p-6 text-center">
                  <div className="w-12 h-12 rounded-full bg-primary/10 flex items-center justify-center">
                    <Sparkles className="h-6 w-6 text-primary" />
                  </div>
                  <div>
                    <p className="text-sm font-medium">Fill in the form and generate</p>
                    <p className="text-xs text-muted-foreground mt-1 max-w-xs">
                      AI will write a complete ATS-optimized job description. Free — no credits used.
                    </p>
                  </div>
                </div>
              )}
              {loading && (
                <div className="flex-1 flex flex-col items-center justify-center min-h-[400px] gap-3">
                  <Loader2 className="h-8 w-8 text-primary animate-spin" />
                  <p className="text-sm text-muted-foreground">Writing your job description…</p>
                </div>
              )}
              {generatedJd && !loading && (
                <Textarea
                  value={generatedJd}
                  onChange={(e) => setGeneratedJd(e.target.value)}
                  className="flex-1 min-h-[400px] resize-none text-sm font-mono leading-relaxed"
                />
              )}
            </div>
          </div>
        </div>

        <DialogFooter className="shrink-0 border-t pt-4 mt-2 gap-2">
          {generatedJd && (
            <Button variant="outline" onClick={handleGenerate} disabled={loading} className="gap-2">
              {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : <RefreshCw className="h-4 w-4" />}
              Regenerate
            </Button>
          )}
          {!generatedJd && (
            <Button variant="outline" onClick={() => handleOpenChange(false)} disabled={loading}>
              Cancel
            </Button>
          )}
          {generatedJd ? (
            <Button onClick={handleUse} disabled={!generatedJd.trim() || loading} className="gap-2">
              <CheckCircle2 className="h-4 w-4" />
              Use this JD
            </Button>
          ) : (
            <Button onClick={handleGenerate} disabled={loading} className="gap-2">
              {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Sparkles className="h-4 w-4" />}
              Generate
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

export default JDGeneratorDialog;

