import { Badge } from "@/components/ui/badge";
import { CheckCircle2, XCircle, AlertTriangle, Star } from "lucide-react";
import { cn } from "@/lib/utils";
import type { Result } from "@/pages/Index";

interface CandidateSummaryCardProps {
  result: Result;
  candidateName: string;
  compact?: boolean;
}

// ── helpers ─────────────────────────────────────────────────────────────────

function scoreColor(score: number): string {
  if (score >= 70) return "text-emerald-600 dark:text-emerald-400";
  if (score >= 40) return "text-amber-600 dark:text-amber-400";
  return "text-red-600 dark:text-red-400";
}

function scoreRingColor(score: number): string {
  if (score >= 70) return "#22c55e"; // green-500
  if (score >= 40) return "#f59e0b"; // amber-500
  return "#ef4444"; // red-500
}

function confidenceLabel(confidence: number | undefined): { label: string; variant: "success" | "warning" | "destructive" } {
  if (!confidence) return { label: "Low confidence", variant: "destructive" };
  if (confidence >= 80) return { label: "High confidence", variant: "success" };
  if (confidence >= 60) return { label: "Medium confidence", variant: "warning" };
  return { label: "Low confidence", variant: "destructive" };
}

function safeStringArray(val: unknown): string[] {
  if (!Array.isArray(val)) return [];
  return val.map((item) => {
    if (typeof item === "string") return item;
    if (item && typeof item === "object" && "text" in item) return String((item as { text: unknown }).text);
    if (item && typeof item === "object" && "value" in item) return String((item as { value: unknown }).value);
    return String(item);
  }).filter(Boolean);
}

// ── Score Ring (SVG) ─────────────────────────────────────────────────────────

interface ScoreRingProps {
  score: number;
  size?: number;
  strokeWidth?: number;
}

function ScoreRing({ score, size = 72, strokeWidth = 6 }: ScoreRingProps) {
  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const clamped = Math.min(Math.max(score, 0), 100);
  const dash = (clamped / 100) * circumference;
  const color = scoreRingColor(score);

  return (
    <div className="relative inline-flex items-center justify-center" style={{ width: size, height: size }}>
      <svg
        width={size}
        height={size}
        viewBox={`0 0 ${size} ${size}`}
        className="-rotate-90"
      >
        {/* Track */}
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          strokeWidth={strokeWidth}
          className="stroke-muted"
        />
        {/* Progress */}
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          stroke={color}
          strokeWidth={strokeWidth}
          strokeLinecap="round"
          strokeDasharray={`${dash} ${circumference}`}
          style={{ transition: "stroke-dasharray 0.5s ease" }}
        />
      </svg>
      <span
        className={cn("absolute text-base font-bold tabular-nums leading-none", scoreColor(score))}
        style={{ fontSize: size < 64 ? "0.875rem" : "1rem" }}
      >
        {Math.round(clamped)}
      </span>
    </div>
  );
}

// ── Mini Progress Bar ────────────────────────────────────────────────────────

function MiniBar({ label, value }: { label: string; value: number }) {
  return (
    <div className="space-y-1">
      <div className="flex items-center justify-between text-xs">
        <span className="text-muted-foreground">{label}</span>
        <span className={cn("font-medium tabular-nums", scoreColor(value))}>{Math.round(value)}</span>
      </div>
      <div className="h-1.5 rounded-full bg-muted overflow-hidden">
        <div
          className={cn(
            "h-full rounded-full transition-all duration-500",
            value >= 70 ? "bg-emerald-500" : value >= 40 ? "bg-amber-500" : "bg-red-500"
          )}
          style={{ width: `${Math.min(value, 100)}%` }}
        />
      </div>
    </div>
  );
}

// ── Main component ────────────────────────────────────────────────────────────

const CandidateSummaryCard = ({ result: r, candidateName, compact = false }: CandidateSummaryCardProps) => {
  const summary = r.explanation_json?.summary || r.summary || null;
  const strengths = safeStringArray(r.strengths_json);
  const gaps = safeStringArray(r.gaps_json);
  const matched = safeStringArray(r.matched_must_haves);
  const missing = safeStringArray(r.missing_must_haves);
  const interviewQs = safeStringArray(r.interview_questions);
  const redFlags = r.missing_skills?.filter(Boolean) ?? [];
  const confInfo = confidenceLabel(r.confidence);

  // Sub-scores: prefer category_scores_json keys, fall back to legacy fields
  const catScores = r.category_scores_json ?? {};
  const skillScore =
    catScores["Skills"]?.score ?? catScores["Technical Skills"]?.score ?? catScores["skills"]?.score
    ?? (r as unknown as Record<string, unknown>).skill_score as number | undefined
    ?? 0;
  const expScore =
    catScores["Experience"]?.score ?? catScores["experience"]?.score
    ?? (r as unknown as Record<string, unknown>).experience_score as number | undefined
    ?? 0;
  const eduScore =
    catScores["Education"]?.score ?? catScores["education"]?.score
    ?? (r as unknown as Record<string, unknown>).education_score as number | undefined
    ?? 0;

  // ── Compact mode ─────────────────────────────────────────────────────────
  if (compact) {
    return (
      <div className="flex items-center gap-3 py-1">
        <ScoreRing score={r.overall_score} size={48} strokeWidth={5} />
        <div className="flex-1 min-w-0">
          {r.hard_fit && (
            <Star className="h-3.5 w-3.5 text-amber-500 inline mr-1" />
          )}
          {summary ? (
            <p className="text-xs text-muted-foreground leading-snug line-clamp-2">{summary}</p>
          ) : (
            <p className="text-xs text-muted-foreground">{candidateName}</p>
          )}
        </div>
      </div>
    );
  }

  // ── Full mode ─────────────────────────────────────────────────────────────
  return (
    <div className="rounded-xl border border-border overflow-hidden bg-card">
      {/* Header row */}
      <div className="px-5 py-4 bg-foreground/[0.02] border-b border-border">
        <div className="flex items-start gap-4">
          <ScoreRing score={r.overall_score} size={72} strokeWidth={6} />
          <div className="flex-1 min-w-0 space-y-2">
            <div className="flex items-center gap-2 flex-wrap">
              <span className="text-sm font-semibold truncate">{candidateName}</span>
              {r.hard_fit && (
                <Badge variant="outline" className="gap-1 text-[11px] border-amber-400/60 text-amber-600 bg-amber-50 dark:bg-amber-900/20 dark:text-amber-400">
                  <Star className="h-2.5 w-2.5 fill-current" /> Hard Fit
                </Badge>
              )}
              <Badge variant={confInfo.variant} className="text-[11px]">{confInfo.label}</Badge>
            </div>
            {/* Sub-score bars */}
            <div className="space-y-1.5">
              {skillScore > 0 && <MiniBar label="Skills" value={skillScore} />}
              {expScore > 0 && <MiniBar label="Experience" value={expScore} />}
              {eduScore > 0 && <MiniBar label="Education" value={eduScore} />}
            </div>
          </div>
        </div>
      </div>

      {/* Body */}
      <div className="px-5 py-4 space-y-5">
        {/* Summary */}
        {summary && (
          <div className="rounded-lg bg-muted/50 border border-border p-4">
            <h4 className="text-xs font-semibold text-primary uppercase tracking-wider mb-2">Summary</h4>
            <p className="text-sm leading-relaxed text-foreground">{summary}</p>
          </div>
        )}

        {/* Must-haves */}
        {(matched.length > 0 || missing.length > 0) && (
          <div className="space-y-2">
            <h4 className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Must-Haves</h4>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-4 gap-y-1.5">
              {matched.map((item, i) => (
                <div key={`m-${i}`} className="flex items-start gap-2 text-sm leading-snug">
                  <CheckCircle2 className="h-3.5 w-3.5 text-emerald-500 shrink-0 mt-0.5" />
                  <span className="text-foreground">{item}</span>
                </div>
              ))}
              {missing.map((item, i) => (
                <div key={`x-${i}`} className="flex items-start gap-2 text-sm leading-snug">
                  <XCircle className="h-3.5 w-3.5 text-red-400 shrink-0 mt-0.5" />
                  <span className="text-muted-foreground">{item}</span>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Strengths + Gaps side by side */}
        {(strengths.length > 0 || gaps.length > 0) && (
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            {strengths.length > 0 && (
              <div className="space-y-1.5">
                <h4 className="text-xs font-semibold uppercase tracking-wider text-emerald-600 dark:text-emerald-400">
                  Strengths
                </h4>
                <ul className="space-y-1.5">
                  {strengths.map((s, i) => (
                    <li key={i} className="flex items-start gap-2 text-sm leading-snug">
                      <span className="mt-2 h-1.5 w-1.5 rounded-full bg-emerald-500 shrink-0" />
                      <span className="text-foreground">{s}</span>
                    </li>
                  ))}
                </ul>
              </div>
            )}
            {gaps.length > 0 && (
              <div className="space-y-1.5">
                <h4 className="text-xs font-semibold uppercase tracking-wider text-red-600 dark:text-red-400">Gaps</h4>
                <ul className="space-y-1.5">
                  {gaps.map((g, i) => (
                    <li key={i} className="flex items-start gap-2 text-sm leading-snug">
                      <span className="mt-2 h-1.5 w-1.5 rounded-full bg-red-500 shrink-0" />
                      <span className="text-foreground">{g}</span>
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </div>
        )}

        {/* Interview Questions */}
        {interviewQs.length > 0 && (
          <div className="space-y-2">
            <h4 className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
              Suggested Interview Questions
            </h4>
            <ol className="space-y-2">
              {interviewQs.map((q, i) => (
                <li key={i} className="flex items-start gap-2.5 text-sm leading-snug">
                  <span className="shrink-0 text-xs font-bold text-primary tabular-nums mt-0.5">{i + 1}.</span>
                  <span className="text-foreground">{q}</span>
                </li>
              ))}
            </ol>
          </div>
        )}

        {/* Red Flags */}
        {redFlags.length > 0 && (
          <div className="rounded-lg border border-amber-400/40 bg-amber-50/50 dark:bg-amber-900/10 p-4 space-y-2">
            <h4 className="text-xs font-semibold uppercase tracking-wider text-amber-700 dark:text-amber-400 flex items-center gap-1.5">
              <AlertTriangle className="h-3.5 w-3.5" />
              Potential Concerns
            </h4>
            <ul className="space-y-1">
              {redFlags.map((flag, i) => (
                <li key={i} className="flex items-start gap-2 text-sm">
                  <span className="mt-2 h-1.5 w-1.5 rounded-full bg-amber-500 shrink-0" />
                  <span className="text-foreground">{flag}</span>
                </li>
              ))}
            </ul>
          </div>
        )}
      </div>
    </div>
  );
};

export default CandidateSummaryCard;

