import { useState, useRef } from "react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Upload, CheckCircle2, AlertTriangle, Loader2, ArrowRight, X } from "lucide-react";

// ── CSV parser (no library) ──────────────────────────────────────────────────

function parseCSVLine(line: string): string[] {
  const result: string[] = [];
  let current = "";
  let inQuotes = false;
  for (const char of line) {
    if (char === '"') {
      inQuotes = !inQuotes;
    } else if (char === "," && !inQuotes) {
      result.push(current.trim());
      current = "";
    } else {
      current += char;
    }
  }
  result.push(current.trim());
  return result;
}

function parseCSV(text: string): { headers: string[]; rows: string[][] } {
  const lines = text.split("\n").filter((l) => l.trim());
  if (lines.length === 0) return { headers: [], rows: [] };
  const headers = parseCSVLine(lines[0]);
  const rows = lines.slice(1).map(parseCSVLine);
  return { headers, rows };
}

// ── Auto-detect field mappings ───────────────────────────────────────────────

type FieldKey = "name" | "email" | "phone" | "linkedin" | "location" | "notes" | "none";

const FIELD_OPTIONS: { value: FieldKey; label: string }[] = [
  { value: "none", label: "— skip —" },
  { value: "name", label: "Name" },
  { value: "email", label: "Email" },
  { value: "phone", label: "Phone" },
  { value: "linkedin", label: "LinkedIn" },
  { value: "location", label: "Location" },
  { value: "notes", label: "Notes" },
];

function autoDetectField(header: string): FieldKey {
  const h = header.toLowerCase().trim();
  if (/^(name|full.?name|candidate.?name|first.?name)$/.test(h)) return "name";
  if (/^(email|e-mail|email.?address)$/.test(h)) return "email";
  if (/^(phone|mobile|tel|telephone|phone.?number)$/.test(h)) return "phone";
  if (/^(linkedin|linkedin.?url|linkedin.?profile)$/.test(h)) return "linkedin";
  if (/^(location|city|address|country)$/.test(h)) return "location";
  if (/^(notes|note|comments|comment|remarks)$/.test(h)) return "notes";
  return "none";
}

// ── Types ────────────────────────────────────────────────────────────────────

interface MappedCandidate {
  name: string;
  email: string;
  phone: string;
  linkedin: string;
  location: string;
  notes: string;
}

type Step = "upload" | "mapping" | "preview" | "importing" | "done";

interface CSVImportDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  jobId: string;
  onImportComplete: () => void;
}

// ── Component ────────────────────────────────────────────────────────────────

const CSVImportDialog = ({ open, onOpenChange, jobId, onImportComplete }: CSVImportDialogProps) => {
  const [step, setStep] = useState<Step>("upload");
  const [headers, setHeaders] = useState<string[]>([]);
  const [rows, setRows] = useState<string[][]>([]);
  const [mappings, setMappings] = useState<Record<number, FieldKey>>({});
  const [importing, setImporting] = useState(false);
  const [progress, setProgress] = useState(0);
  const [importedCount, setImportedCount] = useState(0);
  const [importErrors, setImportErrors] = useState<string[]>([]);
  const [fileError, setFileError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const reset = () => {
    setStep("upload");
    setHeaders([]);
    setRows([]);
    setMappings({});
    setImporting(false);
    setProgress(0);
    setImportedCount(0);
    setImportErrors([]);
    setFileError(null);
  };

  const handleOpenChange = (nextOpen: boolean) => {
    if (!nextOpen && importing) return; // block close during import
    if (!nextOpen) reset();
    onOpenChange(nextOpen);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setFileError(null);

    if (!file.name.endsWith(".csv")) {
      setFileError("Only .csv files are supported");
      return;
    }

    const reader = new FileReader();
    reader.onload = (ev) => {
      const text = ev.target?.result as string;
      const { headers: h, rows: r } = parseCSV(text);
      if (h.length === 0) {
        setFileError("CSV file appears to be empty or invalid");
        return;
      }
      setHeaders(h);
      setRows(r.filter((row) => row.some((cell) => cell.trim())));

      // Auto-detect mappings
      const detected: Record<number, FieldKey> = {};
      h.forEach((header, i) => {
        detected[i] = autoDetectField(header);
      });
      setMappings(detected);
      setStep("mapping");
    };
    reader.onerror = () => setFileError("Failed to read file");
    reader.readAsText(file);
  };

  // Build mapped rows
  const buildMapped = (): MappedCandidate[] => {
    const fieldToColIdx: Partial<Record<FieldKey, number>> = {};
    Object.entries(mappings).forEach(([colIdx, field]) => {
      if (field !== "none") {
        fieldToColIdx[field] = parseInt(colIdx, 10);
      }
    });

    return rows.map((row) => ({
      name: fieldToColIdx.name !== undefined ? (row[fieldToColIdx.name!] ?? "").trim() : "",
      email: fieldToColIdx.email !== undefined ? (row[fieldToColIdx.email!] ?? "").trim() : "",
      phone: fieldToColIdx.phone !== undefined ? (row[fieldToColIdx.phone!] ?? "").trim() : "",
      linkedin: fieldToColIdx.linkedin !== undefined ? (row[fieldToColIdx.linkedin!] ?? "").trim() : "",
      location: fieldToColIdx.location !== undefined ? (row[fieldToColIdx.location!] ?? "").trim() : "",
      notes: fieldToColIdx.notes !== undefined ? (row[fieldToColIdx.notes!] ?? "").trim() : "",
    })).filter((c) => c.name || c.email); // must have at least name or email
  };

  const handleImport = async () => {
    const candidates = buildMapped();
    if (candidates.length === 0) {
      toast.error("No valid candidates to import (each row needs at least a name or email)");
      return;
    }
    setImporting(true);
    setStep("importing");
    setProgress(0);
    const errors: string[] = [];
    let count = 0;

    for (let i = 0; i < candidates.length; i++) {
      const c = candidates[i];
      try {
        const displayName = c.name || c.email || `Candidate ${i + 1}`;
        await (supabase as any).from("resumes").insert({
          job_id: jobId,
          candidate_name: displayName,
          status: "pending",
          parsed_json: {
            name: c.name || null,
            email: c.email || null,
            phone: c.phone || null,
            linkedin_url: c.linkedin || null,
            location: c.location || null,
            notes: c.notes || null,
            source: "csv_import",
          },
          parsed_text: [c.name, c.email, c.phone, c.linkedin, c.location, c.notes]
            .filter(Boolean)
            .join(" "),
        });
        count++;
      } catch (err: unknown) {
        const name = c.name || c.email || `Row ${i + 2}`;
        errors.push(`${name}: ${err instanceof Error ? err.message : "Insert failed"}`);
      }
      setProgress(Math.round(((i + 1) / candidates.length) * 100));
    }

    setImportedCount(count);
    setImportErrors(errors);
    setImporting(false);
    setStep("done");

    if (count > 0) {
      toast.success(`${count} candidate${count !== 1 ? "s" : ""} imported`);
      onImportComplete();
    }
  };

  const mappedCandidates = step === "preview" || step === "importing" || step === "done" ? buildMapped() : [];
  const previewRows = mappedCandidates.slice(0, 5);
  const hasMappedName = Object.values(mappings).includes("name") || Object.values(mappings).includes("email");

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogContent className="max-w-3xl w-full max-h-[90vh] overflow-hidden flex flex-col">
        <DialogHeader className="shrink-0">
          <DialogTitle className="flex items-center gap-2">
            <Upload className="h-5 w-5 text-primary" />
            Import Candidates from CSV
          </DialogTitle>
        </DialogHeader>

        {/* Step indicators */}
        <div className="flex items-center gap-2 shrink-0 pb-4 border-b border-border">
          {(["upload", "mapping", "preview", "importing"] as const).map((s, i) => {
            const stepIndex = ["upload", "mapping", "preview", "importing"].indexOf(step === "done" ? "importing" : step);
            const isDone = i < stepIndex || step === "done";
            const isActive = s === step || (step === "done" && s === "importing");
            return (
              <div key={s} className="flex items-center gap-1.5">
                {i > 0 && <div className="h-px w-4 bg-border" />}
                <div className={`flex items-center gap-1.5 text-xs font-medium ${
                  isActive ? "text-primary" : isDone ? "text-emerald-600 dark:text-emerald-400" : "text-muted-foreground"
                }`}>
                  <div className={`w-5 h-5 rounded-full flex items-center justify-center text-[10px] font-bold border ${
                    isDone ? "bg-emerald-500 border-emerald-500 text-white" : isActive ? "bg-primary border-primary text-primary-foreground" : "border-border text-muted-foreground"
                  }`}>
                    {isDone ? <CheckCircle2 className="h-3 w-3" /> : i + 1}
                  </div>
                  <span className="capitalize hidden sm:inline">{s}</span>
                </div>
              </div>
            );
          })}
        </div>

        <div className="flex-1 overflow-y-auto min-h-0">
          {/* Step 1: Upload */}
          {step === "upload" && (
            <div className="py-8 flex flex-col items-center gap-4">
              <div
                className="w-full border-2 border-dashed rounded-lg p-10 flex flex-col items-center gap-3 cursor-pointer hover:border-primary/50 hover:bg-primary/[0.02] transition-colors"
                onClick={() => fileInputRef.current?.click()}
              >
                <div className="w-12 h-12 rounded-lg bg-muted flex items-center justify-center">
                  <Upload className="h-6 w-6 text-primary" />
                </div>
                <div className="text-center">
                  <p className="text-sm font-medium">Click to select a CSV file</p>
                  <p className="text-xs text-muted-foreground mt-1">
                    Must include at least one column for candidate name or email
                  </p>
                </div>
                <input
                  ref={fileInputRef}
                  type="file"
                  accept=".csv"
                  className="hidden"
                  onChange={handleFileChange}
                />
              </div>
              {fileError && (
                <div className="flex items-center gap-2 text-sm text-destructive">
                  <AlertTriangle className="h-4 w-4 shrink-0" />
                  {fileError}
                </div>
              )}
              <p className="text-xs text-muted-foreground text-center max-w-sm">
                Supported columns: Name, Email, Phone, LinkedIn, Location, Notes. Column headers are auto-detected.
              </p>
            </div>
          )}

          {/* Step 2: Mapping */}
          {step === "mapping" && (
            <div className="py-4 space-y-4">
              <p className="text-sm text-muted-foreground">
                Map your CSV columns to Rankora fields. Auto-detected mappings are shown — adjust as needed.
              </p>
              <div className="rounded-lg border border-border overflow-hidden">
                <table className="w-full text-sm">
                  <thead className="bg-muted/50">
                    <tr>
                      <th className="text-left px-4 py-2.5 text-xs font-semibold text-muted-foreground w-1/2">CSV Column</th>
                      <th className="text-left px-4 py-2.5 text-xs font-semibold text-muted-foreground w-1/2">Map to Field</th>
                    </tr>
                  </thead>
                  <tbody>
                    {headers.map((header, i) => (
                      <tr key={i} className="border-t border-border">
                        <td className="px-4 py-2.5 font-medium text-foreground">{header}</td>
                        <td className="px-4 py-2.5">
                          <Select
                            value={mappings[i] ?? "none"}
                            onValueChange={(v) =>
                              setMappings((prev) => ({ ...prev, [i]: v as FieldKey }))
                            }
                          >
                            <SelectTrigger className="h-8 text-xs w-40">
                              <SelectValue />
                            </SelectTrigger>
                            <SelectContent>
                              {FIELD_OPTIONS.map((opt) => (
                                <SelectItem key={opt.value} value={opt.value} className="text-xs">
                                  {opt.label}
                                </SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              <p className="text-xs text-muted-foreground">
                {rows.length} data row{rows.length !== 1 ? "s" : ""} detected in file.
              </p>
            </div>
          )}

          {/* Step 3: Preview */}
          {step === "preview" && (
            <div className="py-4 space-y-4">
              <p className="text-sm text-muted-foreground">
                Preview of first {Math.min(5, previewRows.length)} candidates. {mappedCandidates.length} total will be imported.
              </p>
              <div className="rounded-lg border border-border overflow-hidden overflow-x-auto">
                <table className="w-full text-sm">
                  <thead className="bg-muted/50">
                    <tr>
                      {["Name", "Email", "Phone", "LinkedIn", "Location"].map((col) => (
                        <th key={col} className="text-left px-4 py-2.5 text-xs font-semibold text-muted-foreground whitespace-nowrap">{col}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {previewRows.map((c, i) => (
                      <tr key={i} className="border-t border-border">
                        <td className="px-4 py-2.5 font-medium truncate max-w-[150px]">{c.name || <span className="text-muted-foreground">—</span>}</td>
                        <td className="px-4 py-2.5 truncate max-w-[150px]">{c.email || <span className="text-muted-foreground">—</span>}</td>
                        <td className="px-4 py-2.5 truncate max-w-[120px]">{c.phone || <span className="text-muted-foreground">—</span>}</td>
                        <td className="px-4 py-2.5 truncate max-w-[120px]">{c.linkedin || <span className="text-muted-foreground">—</span>}</td>
                        <td className="px-4 py-2.5 truncate max-w-[120px]">{c.location || <span className="text-muted-foreground">—</span>}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              {mappedCandidates.length > 5 && (
                <p className="text-xs text-muted-foreground">
                  + {mappedCandidates.length - 5} more candidates not shown
                </p>
              )}
            </div>
          )}

          {/* Step 4: Importing */}
          {step === "importing" && (
            <div className="py-12 flex flex-col items-center gap-4">
              <Loader2 className="h-10 w-10 text-primary animate-spin" />
              <p className="text-sm font-medium">Importing candidates…</p>
              <div className="w-full max-w-sm space-y-1.5">
                <Progress value={progress} className="h-2" />
                <p className="text-xs text-center text-muted-foreground">{progress}%</p>
              </div>
            </div>
          )}

          {/* Step 5: Done */}
          {step === "done" && (
            <div className="py-8 flex flex-col items-center gap-4">
              <div className="w-14 h-14 rounded-full bg-emerald-100 dark:bg-emerald-900/30 flex items-center justify-center">
                <CheckCircle2 className="h-7 w-7 text-emerald-600 dark:text-emerald-400" />
              </div>
              <div className="text-center">
                <p className="text-base font-semibold">Import complete</p>
                <p className="text-sm text-muted-foreground mt-1">
                  {importedCount} candidate{importedCount !== 1 ? "s" : ""} added to this job
                </p>
              </div>
              {importErrors.length > 0 && (
                <div className="w-full rounded-lg border border-destructive/40 bg-destructive/5 p-4 space-y-2">
                  <p className="text-xs font-semibold text-destructive flex items-center gap-1.5">
                    <AlertTriangle className="h-3.5 w-3.5" />
                    {importErrors.length} row{importErrors.length !== 1 ? "s" : ""} failed
                  </p>
                  <ul className="space-y-1 max-h-32 overflow-y-auto">
                    {importErrors.map((err, i) => (
                      <li key={i} className="text-xs text-destructive">{err}</li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
          )}
        </div>

        <DialogFooter className="shrink-0 border-t pt-4 mt-2 gap-2">
          {step === "done" ? (
            <Button onClick={() => handleOpenChange(false)}>Done</Button>
          ) : step === "mapping" ? (
            <>
              <Button variant="ghost" onClick={() => setStep("upload")} disabled={importing}>
                Back
              </Button>
              <Button
                onClick={() => setStep("preview")}
                disabled={!hasMappedName}
                className="gap-2"
              >
                Preview <ArrowRight className="h-4 w-4" />
              </Button>
            </>
          ) : step === "preview" ? (
            <>
              <Button variant="ghost" onClick={() => setStep("mapping")}>Back</Button>
              <Button onClick={handleImport} className="gap-2">
                Import {mappedCandidates.length} Candidate{mappedCandidates.length !== 1 ? "s" : ""}
                <ArrowRight className="h-4 w-4" />
              </Button>
            </>
          ) : step === "upload" ? (
            <Button variant="ghost" onClick={() => handleOpenChange(false)}>Cancel</Button>
          ) : null}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

export default CSVImportDialog;

